523	      .control-btn {
524	        background: rgba(255, 255, 255, 0.35);
525	        border-color: rgba(255, 255, 255, 0.6);
526	        color: rgba(0, 0, 0, 0.75);
527	      }
528	      .control-btn:hover {
529	        background: rgba(255, 255, 255, 0.5);
530	        border-color: rgba(255, 255, 255, 0.9);
531	        color: rgba(0, 0, 0, 0.85);
532	      }
533	      .control-btn:active {
534	        background: rgba(255, 255, 255, 0.4);
535	      }
536	      .hint {
537	        color: rgba(0, 0, 0, 0.8);
538	        text-shadow: 0 1px 2px rgba(255, 255, 255, 0.6);
539	      }
540	      .keyboard-hint {
541	        opacity: 1;
542	        color: rgba(0, 0, 0, 0.75);
543	      }
544	      .mode-indicator {
545	        color: rgba(0, 0, 0, 0.8);
546	        text-shadow: 0 1px 3px rgba(255, 255, 255, 0.5);
547	      }
548	      .keyboard-hint kbd {
549	        background: rgba(255, 255, 255, 0.5);
