560	<body>
561	  <button type="button" class="help-btn" id="help-btn" aria-label="Show keyboard shortcuts" title="Help (press ?)">?</button>
562	
563	  <div class="modal" id="help-modal" role="dialog" aria-labelledby="modal-header" aria-modal="true">
564	    <div class="modal-content">
565	      <button type="button" class="modal-close" id="modal-close" aria-label="Close help">✕</button>
566	      <div class="modal-header" id="modal-header">Keyboard Shortcuts</div>
567	      <div class="modal-shortcuts">
568	        <div class="shortcut-item">
569	          <span class="shortcut-key">C</span>
570	          <span class="shortcut-desc">Cycle to next color</span>
571	        </div>
572	        <div class="shortcut-item">
573	          <span class="shortcut-key">X</span>
574	          <span class="shortcut-desc">Random color</span>
575	        </div>
576	        <div class="shortcut-item">
577	          <span class="shortcut-key">R</span>
578	          <span class="shortcut-desc">Reset to default</span>
579	        </div>
580	        <div class="shortcut-item">
581	          <span class="shortcut-key">Space</span>
582	          <span class="shortcut-desc">Toggle active state</span>
583	        </div>
584	        <div class="shortcut-item">
585	          <span class="shortcut-key">↩</span>
586	          <span class="shortcut-desc">Toggle active state</span>
587	        </div>
588	        <div class="shortcut-item">
589	          <span class="shortcut-key">Esc</span>
590	          <span class="shortcut-desc">Reset to default</span>
591	        </div>
592	        <div class="shortcut-item">
593	          <span class="shortcut-key">?</span>
594	          <span class="shortcut-desc">Show this help</span>
595	        </div>
