602	      <svg viewBox="0 0 400 400" preserveAspectRatio="xMidYMid meet" aria-hidden="true" role="presentation">
603	        <circle cx="200" cy="200" r="200"/>
604	      </svg>
605	    </button>
606	    <div class="mode-indicator" id="mode-indicator" aria-live="polite" aria-atomic="true"></div>
607	    <div class="hint" id="hint-text" role="status" aria-live="polite" aria-relevant="text">Click or tap to activate</div>
608	    <div class="controls" role="group" aria-label="Circle controls">
609	      <button type="button" class="control-btn" id="cycle-btn" aria-label="Cycle to next color">Cycle Color</button>
610	      <button type="button" class="control-btn" id="random-btn" aria-label="Jump to random color">Random</button>
611	      <button type="button" class="control-btn" id="reset-btn" aria-label="Reset to default state">Reset</button>
