645	      const el = {
646	        circle: document.getElementById('decorative-circle'),
647	        hint: document.getElementById('hint-text'),
648	        modeIndicator: document.getElementById('mode-indicator'),
649	        cycleBtn: document.getElementById('cycle-btn'),
650	        randomBtn: document.getElementById('random-btn'),
651	        resetBtn: document.getElementById('reset-btn'),
652	        helpBtn: document.getElementById('help-btn'),
653	        helpModal: document.getElementById('help-modal'),
654	        modalClose: document.getElementById('modal-close')
655	      };
656	
657	      let state = { active: false, colorMode: 0 };
658	      let tapCount = 0;
659	      let tapTimeout = null;
660	      let animatingColorShift = false;
