665	
666	      const getColorClass = (mode) => COLORS[mode % COLORS.length]?.class || '';
667	      const getColorName = (mode) => COLORS[mode % COLORS.length]?.name || '';
668	
669	      const storage = {
670	        save() {
671	          clearTimeout(saveTimeout);
672	          saveTimeout = setTimeout(() => {
673	            try {
674	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
675	            } catch (e) {
676	              if (e?.name === 'QuotaExceededError') {
677	                console.warn('Storage quota exceeded');
678	              }
679	            }
680	          }, CONFIG.saveDebounceDuration);
681	        },
682	        load() {
683	          try {
684	            const saved = localStorage.getItem(CONFIG.storageKey);
685	            if (saved) {
