713	          }
714	        }
715	      };
716	
717	      const updateUI = () => {
718	        const isActive = state.active;
719	        const hint = isTouch
720	          ? (isActive ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle')
