730	        }
731	      };
732	
733	      const applyState = () => {
734	        updateClasses();
735	        updateUI();
736	      };
737	
738	      const modal = {
739	        previousFocus: null,
740	        open() {
741	          if (!el.helpModal || !el.modalClose) return;
742	          modal.previousFocus = document.activeElement;
743	          el.helpModal.classList.add('active');
744	          el.modalClose.focus();
745	          document.body.style.overflow = 'hidden';
746	        },
747	        close() {
748	          if (!el.helpModal) return;
749	          el.helpModal.classList.remove('active');
750	          document.body.style.overflow = '';
751	          modal.previousFocus?.focus?.();
752	        }
753	      };
754	
755	      const toggleActive = () => {
756	        state.active = !state.active;
757	        haptic(10);
758	        applyState();
759	        storage.save();
760	      };
761	
762	      const changeColor = (newMode, hapticPattern = 20) => {
763	        if (animatingColorShift || !el.circle) return;
764	        animatingColorShift = true;
765	        state.colorMode = newMode;
766	        state.active = true;
767	        haptic(hapticPattern);
768	        el.circle.classList.add('color-shifting');
769	        const timeoutId = setTimeout(() => {
770	          el.circle?.classList.remove('color-shifting');
771	          animatingColorShift = false;
772	        }, CONFIG.colorShiftDuration);
773	        applyState();
774	        storage.save();
775	        return timeoutId;
776	      };
777	
778	      const cycleColor = () => changeColor((state.colorMode + 1) % COLORS.length);
779	      const randomizeColor = () => changeColor(getRandomColorMode(), [20, 10, 20]);
780	
781	      const resetState = () => {
782	        state = { active: false, colorMode: 0 };
783	        haptic(10);
784	        applyState();
785	        storage.save();
786	      };
787	
788	      const handleTouchEnd = () => {
789	        tapCount++;
790	        haptic(10);
791	        clearTimeout(tapTimeout);
792	
793	        if (tapCount === 1) {
