796	              toggleActive();
797	            }
798	            tapCount = 0;
799	          }, CONFIG.tapDelay);
800	        } else if (tapCount >= 2) {
801	          tapCount = 0;
802	          cycleColor();
803	        }
804	      };
805	
806	      const keyHandlers = {
807	        ' ': toggleActive,
808	        'enter': toggleActive,
809	        'escape': resetState,
810	        'c': cycleColor,
811	        'x': randomizeColor,
812	        'r': resetState,
813	        '?': modal.open
814	      };
815	
816	      const handleKeyDown = (e) => {
817	        const key = e.key.toLowerCase();
818	        const handler = keyHandlers[key];
819	        if (!handler) return;
820	
821	        const now = Date.now();
822	        if (now - lastKeyTime < CONFIG.keyDebounce) return;
823	
824	        e.preventDefault();
825	        try {
826	          handler();
827	          lastKeyTime = now;
828	        } catch (err) {
829	          console.error('Keyboard handler error:', err);
830	        }
831	      };
832	
833	      const handleModalKeyDown = (e) => {
834	        if (!el.helpModal?.classList.contains('active')) return;
835	
836	        if (e.key === 'Escape') {
837	          e.preventDefault();
838	          modal.close();
839	          return;
840	        }
841	
842	        if (e.key === 'Tab') {
843	          const focusableElements = Array.from(el.helpModal.querySelectorAll('button, [tabindex]'));
844	          if (focusableElements.length === 0) return;
845	
846	          const firstElement = focusableElements[0];
847	          const lastElement = focusableElements[focusableElements.length - 1];
848	          const activeElement = document.activeElement;
