867	        }
868	      };
869	
870	      const attachListener = (element, event, handler, options) => {
871	        element?.addEventListener(event, handler, options);
872	      };
873	
874	      const initListeners = () => {
875	        if (!el.circle) return;
876	
877	        attachListener(el.circle, 'blur', () => {
878	          tapCount = 0;
879	          clearTimeout(tapTimeout);
880	        });
881	
882	        if (isTouch) {
