  element?.addEventListener(event, handler, options);
};

const initListeners = () => {
  if (!el.circle) return;

  attachListener(el.circle, 'blur', () => {
    tapCount = 0;
    clearTimeout(tapTimeout);
  });

  if (isTouch) {
    attachListener(el.circle, 'touchend', handleTouchEnd, { passive: true });
    if (window.PointerEvent) {
      attachListener(el.circle, 'pointerup', handleTouchEnd, { passive: true });
    }
  } else {
    attachListener(el.circle, 'click', toggleActive, { passive: true });
    attachListener(el.circle, 'dblclick', cycleColor, { passive: true });
  }

  document.addEventListener('keydown', handleKeyDown);

  attachListener(el.cycleBtn, 'click', cycleColor, { passive: true });
  attachListener(el.randomBtn, 'click', randomizeColor, { passive: true });
  attachListener(el.resetBtn, 'click', resetState, { passive: true });
  attachListener(el.helpBtn, 'click', modal.open, { passive: true });
  attachListener(el.modalClose, 'click', modal.close, { passive: true });
  attachListener(el.helpModal, 'click', handleModalBackdropClick, { passive: true });
  attachListener(el.helpModal, 'keydown', handleModalKeyDown);
};

